<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { useRouter } from 'vue-router'
import { api, type StudyDocument } from '../lib/api'
import { date, message, notify, registerIdentityGuard } from '../lib/state'
import { onBeforeUnmount } from 'vue'
import Icon from '../components/Icon.vue'
import Modal from '../components/Modal.vue'
const router=useRouter(),documents=ref<StudyDocument[]>([]),loading=ref(true),uploading=ref(false),error=ref(''),remove=ref<StudyDocument>(),deleting=ref(false),input=ref<HTMLInputElement>()
const unregister=registerIdentityGuard(reason=>reason==='preserve'||!uploading.value&&!deleting.value)
onBeforeUnmount(unregister)
async function load(){loading.value=true;error.value='';try{documents.value=(await api.documents()).documents}catch(e){error.value=message(e)}finally{loading.value=false}}
async function upload(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;error.value='';if(file.size>20*1024*1024){error.value='文件超过 20 MiB，请拆分后再上传';return}if(!file.name.toLowerCase().endsWith('.pdf')){error.value='请选择 PDF 文件';return}uploading.value=true;try{const result=await api.uploadDocument(file);notify(result.duplicate?'该教材已存在，已打开原教材':'教材已导入');await router.push(`/documents/${result.document.id}`)}catch(e){error.value=message(e)}finally{uploading.value=false;if(input.value)input.value.value=''}}
async function deleteDocument(){if(!remove.value)return;deleting.value=true;try{await api.deleteDocument(remove.value.id);documents.value=documents.value.filter(d=>d.id!==remove.value?.id);remove.value=undefined;notify('教材已删除，已有题目引用快照保留')}catch(e){error.value=message(e)}finally{deleting.value=false}}
onMounted(load)
</script>
<template><div class="page-container"><header class="page-heading"><div><p class="heading-note">每个问题，都有可以回到的原文</p><h1>我的教材</h1><p>私有 PDF 教材库，按页阅读、选取引文，让练习有据可查</p></div><button class="button primary" :disabled="uploading" @click="input?.click()"><Icon name="plus"/>{{uploading?'正在解析教材…':'上传 PDF'}}</button><input ref="input" type="file" accept="application/pdf,.pdf" class="visually-hidden" aria-label="上传 PDF 教材" :disabled="uploading" @change="upload"/></header><section class="document-intro"><Icon name="lock"/><div><h3>原文件只属于你的学习空间</h3><p>公开题集仅分享选定的摘录。每份教材最多 20 MiB、200 页、200 万字；支持文字 PDF，不提供 OCR。页码始终使用 PDF 物理页。</p></div></section><p v-if="error" class="error" role="alert">{{error}}<button class="text-button" @click="load">重新读取列表</button></p><div v-if="loading" class="loading">正在读取教材…</div><div v-else-if="!documents.length" class="empty-state"><Icon name="book"/><h2>从一份熟悉的教材开始</h2><p>上传后可以直接阅读和绑定引用，无需配置模型</p><button class="button primary" :disabled="uploading" @click="input?.click()">选择 PDF 文件</button></div><div v-else class="document-list"><article v-for="document in documents" :key="document.id" class="document-row"><span class="set-symbol"><Icon name="document"/></span><RouterLink :to="`/documents/${document.id}`" class="document-title"><h3>{{document.title}}</h3><p>{{document.filename}}</p><div class="set-meta"><span>{{document.pageCount}} 物理页</span><span>{{document.textPageCount}} 页可提取文字</span><span>{{date(document.createdAt)}}</span></div><p v-if="document.warnings.length" class="document-warning">{{document.warnings.join('；')}}</p></RouterLink><RouterLink :to="`/documents/${document.id}`" class="button">阅读<Icon name="right"/></RouterLink><button class="icon-button danger" :aria-label="`删除教材 ${document.title}`" @click="remove=document"><Icon name="delete"/></button></article></div><Modal :open="!!remove" title="删除原教材？" @close="!deleting&&(remove=undefined)"><p>{{remove?.title}} 的原 PDF 和全文将不可再访问。已保存到题集和学习记录中的引用摘录仍然保留。</p><div class="modal-actions"><button class="button" :disabled="deleting" @click="remove=undefined">取消</button><button class="button danger-fill" :disabled="deleting" @click="deleteDocument">{{deleting?'正在删除…':'删除教材'}}</button></div></Modal></div></template>
